// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "./IFeeManager.sol";

/**
 * @title FeeManager
 * @notice Stores versioned fee schedules and treasury settings
 */
contract FeeManager is Ownable2Step, IFeeManager {
    uint16 public constant BPS_DENOMINATOR = 10_000;

    address public treasury;
    uint256 public currentFeeVersion;

    mapping(uint256 => FeeConfig) private _feeConfigs;
    mapping(uint256 => bytes32) private _feeScheduleHashes;

    error InvalidBps();
    error InvalidTreasury();
    error FeeConfigNotFound(uint256 version);

    event FeeConfigCreated(
        uint256 indexed version,
        uint16 saleFeeBps,
        uint16 saleServicerFeeBps,
        uint16 interestFeeBps,
        uint16 interestServicerFeeBps,
        uint16 foreclosureFeeBps,
        uint16 preSaleProfitSharingBps,
        bytes32 feeHash
    );
    event CurrentFeeVersionUpdated(uint256 indexed oldVersion, uint256 indexed newVersion);
    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);

    constructor(address initialOwner, address initialTreasury) Ownable(initialOwner) {
        if (initialTreasury == address(0)) revert InvalidTreasury();
        treasury = initialTreasury;
    }

    function createFeeConfig(FeeConfig calldata config) external onlyOwner returns (uint256 version) {
        _validateConfig(config);
        version = currentFeeVersion + 1;
        currentFeeVersion = version;
        _feeConfigs[version] = config;
        bytes32 feeHash = _hashConfig(config);
        _feeScheduleHashes[version] = feeHash;
        emit FeeConfigCreated(
            version,
            config.saleFeeBps,
            config.saleServicerFeeBps,
            config.interestFeeBps,
            config.interestServicerFeeBps,
            config.foreclosureFeeBps,
            config.preSaleProfitSharingBps,
            feeHash
        );
        emit CurrentFeeVersionUpdated(version - 1, version);
    }

    function updateTreasury(address newTreasury) external onlyOwner {
        if (newTreasury == address(0)) revert InvalidTreasury();
        address oldTreasury = treasury;
        treasury = newTreasury;
        emit TreasuryUpdated(oldTreasury, newTreasury);
    }

    function getFeeConfig(uint256 version) external view returns (FeeConfig memory) {
        if (_feeScheduleHashes[version] == bytes32(0)) revert FeeConfigNotFound(version);
        return _feeConfigs[version];
    }

    function feeScheduleHash(uint256 version) external view returns (bytes32) {
        if (_feeScheduleHashes[version] == bytes32(0)) revert FeeConfigNotFound(version);
        return _feeScheduleHashes[version];
    }

    function _hashConfig(FeeConfig calldata config) internal pure returns (bytes32) {
        return keccak256(
            abi.encode(
                config.saleFeeBps,
                config.saleServicerFeeBps,
                config.interestFeeBps,
                config.interestServicerFeeBps,
                config.foreclosureFeeBps,
                config.preSaleProfitSharingBps
            )
        );
    }

    function _validateConfig(FeeConfig calldata config) internal pure {
        if (
            config.saleFeeBps > BPS_DENOMINATOR ||
            config.saleServicerFeeBps > BPS_DENOMINATOR ||
            config.interestFeeBps > BPS_DENOMINATOR ||
            config.interestServicerFeeBps > BPS_DENOMINATOR ||
            config.foreclosureFeeBps > BPS_DENOMINATOR ||
            config.preSaleProfitSharingBps > BPS_DENOMINATOR
        ) {
            revert InvalidBps();
        }
    }
}

