// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "./PropertyNFT.sol";
import "../RwaERC-3643/proxy/TokenProxy.sol";
import "../RwaERC-3643/token/Token.sol";

contract FractionalVault is Initializable, AccessControlUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    PropertyNFT public propertyNFT;
    address public identityRegistry;
    address public implementationAuthority;

    struct FractionalData {
        address tokenAddress;
        uint256 totalShares;
        address originalOwner;
        address complianceAddress;
        // Set once redeemShares releases the NFT. Kept (rather than deleting
        // the record) so tokenAddress stays resolvable afterward — shares
        // still held by holders who never sold back remain traceable to
        // their property, and the marketplace's anti-squatting lookup
        // doesn't go stale — while blocking a second redemption.
        bool redeemed;
    }

    mapping(uint256 => FractionalData) public fractionalData;

    error ZeroAddress();
    error NotOwner();
    error InvalidPrice();
    error ZeroShares();
    error NotFractionalized();
    error AlreadyRedeemed();
    error NotTokenOwner();
    error TransferFailed();

    event Fractionalized(uint256 indexed nftId, address shareToken, address complianceAddress, uint256 totalShares);
    event SharesRedeemed(uint256 indexed nftId, address owner, uint256 sharesBurned);
    event IdentityRegistrySet(address indexed identityRegistry);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _propertyNFT,
        address _initialOwner,
        address _identityRegistry,
        address _implementationAuthority
    ) external initializer {
        if (_propertyNFT == address(0) || _identityRegistry == address(0) || _implementationAuthority == address(0)) {
            revert ZeroAddress();
        }

        __AccessControl_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        propertyNFT = PropertyNFT(_propertyNFT);
        identityRegistry = _identityRegistry;
        implementationAuthority = _implementationAuthority;

        _grantRole(DEFAULT_ADMIN_ROLE, _initialOwner);
        _grantRole(UPGRADER_ROLE, _initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    // Share tokens are whole, indivisible units — decimals is fixed at 0, so
    // 1 token == 1 share == _basePrice's worth of the property (e.g. a $40
    // base price means every share is a $40 slice; there is no way to hold
    // or trade a fraction of a share).
    uint8 public constant SHARE_DECIMALS = 0;

    function fractionalizeProperty(uint256 _nftId, address _complianceAddress, uint256 _basePrice)
        external
        nonReentrant
    {
        if (_complianceAddress == address(0)) revert ZeroAddress();
        if (_basePrice == 0) revert InvalidPrice();
        if (propertyNFT.ownerOf(_nftId) != msg.sender) revert NotOwner();

        // Get data from PropertyNFT struct
        (string memory name, string memory symbol, , , , uint256 propertyPrice, ) = propertyNFT.propertyDetails(_nftId);
        if (propertyPrice == 0) revert InvalidPrice();

        // Calculate total shares — whole shares only, no decimals scaling.
        uint256 totalShares = propertyPrice / _basePrice;
        if (totalShares == 0) revert ZeroShares();

        // Lock the NFT
        propertyNFT.lockNFT(_nftId, msg.sender);

        // Deploy the ERC3643 share token via the shared TREXImplementationAuthority
        TokenProxy shareTokenProxy = new TokenProxy(
            implementationAuthority,
            identityRegistry,
            _complianceAddress,
            name,
            symbol,
            SHARE_DECIMALS,
            address(0),
            _nftId
        );
        Token shareToken = Token(address(shareTokenProxy));

        if (shareToken.owner() != address(this)) revert NotTokenOwner();

        shareToken.addAgent(address(this));

        // Token.init() leaves the token paused by default; unpause it so the
        // minted shares are actually transferable (OrderBook/Marketplace
        // trading, redemption) once fractionalization completes.
        shareToken.unpause();

        // Mint tokens to the original NFT owner
        shareToken.mint(msg.sender, totalShares);

        if (shareToken.owner() != msg.sender) {
            shareToken.transferOwnership(msg.sender);
        }

        // Save data
        fractionalData[_nftId] = FractionalData({
            tokenAddress: address(shareToken),
            totalShares: totalShares,
            originalOwner: msg.sender,
            complianceAddress: _complianceAddress,
            redeemed: false
        });

        emit Fractionalized(_nftId, address(shareToken), _complianceAddress, totalShares);
    }

    /// @notice Burn the caller's shares and release the NFT to them.
    /// @dev    Only the original owner may redeem. There is deliberately no
    ///         requirement to hold 100% of the supply: the owner buys back
    ///         outstanding shares through the marketplace's escrowed buyback
    ///         before redeeming, so any shares still held by third parties at
    ///         this point are ones their holders chose not to sell back.
    function redeemShares(uint256 _nftId) external nonReentrant {
        FractionalData memory data = fractionalData[_nftId];
        if (data.tokenAddress == address(0)) revert NotFractionalized();
        if (data.redeemed) revert AlreadyRedeemed();
        if (msg.sender != data.originalOwner) revert NotOwner();

        Token token = Token(data.tokenAddress);
        uint256 userBalance = token.balanceOf(msg.sender);
        if (userBalance == 0) revert ZeroShares();

        // Burn user tokens and unlock NFT
        if (!token.transferFrom(msg.sender, address(this), userBalance)) revert TransferFailed();
        token.burn(address(this), userBalance);

        propertyNFT.unlockNFT(_nftId, msg.sender);
        fractionalData[_nftId].redeemed = true;

        emit SharesRedeemed(_nftId, msg.sender, userBalance);
    }

    function getTokenAddressForProperty(uint256 _nftId) external view returns (address) {
        return fractionalData[_nftId].tokenAddress;
    }

    function setIdentityRegistry(address _identityRegistry) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_identityRegistry == address(0)) revert ZeroAddress();
        identityRegistry = _identityRegistry;
        emit IdentityRegistrySet(_identityRegistry);
    }

    uint256[45] private __gap;
}

