// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./IFeeManager.sol";

contract Orderbook is Initializable, AccessControlUpgradeable, ReentrancyGuardUpgradeable, UUPSUpgradeable {
    using SafeERC20 for IERC20;

    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    struct Order {
        uint256 id;
        address token;
        address seller;
        uint256 amount;
        uint256 pricePerToken;
        bool active;
    }

    IERC20 public usdc;
    uint256 public nextOrderId;
    mapping(uint256 => Order) public orders;
    IFeeManager public feeManager;

    error ZeroAddress();
    error InvalidAmount();
    error InvalidPrice();
    error OrderInactive();
    error NotYourOrder();
    error InvalidTreasury();

    event OrderCreated(
        uint256 indexed orderId,
        address indexed seller,
        address indexed token,
        uint256 amount,
        uint256 pricePerToken
    );

    event OrderFilled(
        uint256 indexed orderId,
        address indexed buyer,
        uint256 amount,
        uint256 totalCost,
        uint256 fee
    );

    event OrderCancelled(uint256 indexed orderId, address indexed seller);
    event FeeManagerUpdated(address indexed oldFeeManager, address indexed newFeeManager);
    event SaleFeePaid(
        uint256 indexed orderId, address indexed buyer, address indexed treasury, uint256 feeAmount, uint256 feeVersion
    );

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner, IERC20 _usdc, address feeManagerAddress) external initializer {
        if (address(_usdc) == address(0) || feeManagerAddress == address(0)) revert ZeroAddress();

        __AccessControl_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        usdc = _usdc;
        feeManager = IFeeManager(feeManagerAddress);
        // Reserve 0 as "no such order" — orders[0] on a never-created order
        // already reads as { id: 0, active: false, ... } by default, but
        // starting real ids at 1 keeps id 0 unambiguous rather than
        // colliding with the first real order.
        nextOrderId = 1;

        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(UPGRADER_ROLE, initialOwner);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    function setFeeManager(address _feeManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_feeManager == address(0)) revert ZeroAddress();
        address oldFeeManager = address(feeManager);
        feeManager = IFeeManager(_feeManager);
        emit FeeManagerUpdated(oldFeeManager, _feeManager);
    }

    function createOrder(address token, uint256 amount, uint256 pricePerToken) external nonReentrant {
        if (token == address(0)) revert ZeroAddress();
        if (amount == 0) revert InvalidAmount();
        if (pricePerToken == 0) revert InvalidPrice();

        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        uint256 orderId = nextOrderId++;
        orders[orderId] = Order({
            id: orderId,
            token: token,
            seller: msg.sender,
            amount: amount,
            pricePerToken: pricePerToken,
            active: true
        });

        emit OrderCreated(orderId, msg.sender, token, amount, pricePerToken);
    }

    function fillOrder(uint256 orderId, uint256 buyAmount) external nonReentrant {
        Order storage order = orders[orderId];
        if (!order.active) revert OrderInactive();
        if (buyAmount == 0 || buyAmount > order.amount) revert InvalidAmount();

        // Share tokens are whole units (FractionalVault.SHARE_DECIMALS == 0),
        // so pricePerToken is denominated directly in usdc units per whole
        // share — no decimals scaling to undo here.
        uint256 totalCost = buyAmount * order.pricePerToken;
        if (totalCost == 0) revert InvalidAmount();
        uint256 fee = _collectSaleFee(orderId, totalCost, msg.sender);

        usdc.safeTransferFrom(msg.sender, order.seller, totalCost);

        IERC20(order.token).safeTransfer(msg.sender, buyAmount);
        order.amount -= buyAmount;

        if (order.amount == 0) {
            order.active = false;
        }
        emit OrderFilled(orderId, msg.sender, buyAmount, totalCost, fee);
    }

    function _collectSaleFee(uint256 orderId, uint256 totalPrice, address buyer) internal returns (uint256 fee) {
        uint256 feeVersion = feeManager.currentFeeVersion();
        IFeeManager.FeeConfig memory feeConfig = feeManager.getFeeConfig(feeVersion);
        if (feeConfig.saleFeeBps == 0) return 0;

        address treasury = feeManager.treasury();
        if (treasury == address(0)) revert InvalidTreasury();

        fee = (totalPrice * feeConfig.saleFeeBps) / feeManager.BPS_DENOMINATOR();
        usdc.safeTransferFrom(buyer, treasury, fee);
        emit SaleFeePaid(orderId, buyer, treasury, fee, feeVersion);
    }

    function cancelOrder(uint256 orderId) external nonReentrant {
        Order storage order = orders[orderId];
        if (!order.active) revert OrderInactive();
        if (order.seller != msg.sender) revert NotYourOrder();

        order.active = false;
        IERC20(order.token).safeTransfer(msg.sender, order.amount);

        emit OrderCancelled(orderId, msg.sender);
    }

    uint256[47] private __gap;
}

project/contracts/TrueFraction/PropertyN.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/token/ERC721/extensions/ERC721URIStorageUpgradeable.sol";

contract PropertyNFT is
    Initializable,
    ERC721Upgradeable,
    ERC721URIStorageUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
    bytes32 public constant AUTHORITY_ROLE = keccak256("AUTHORITY_ROLE");

    uint256 public nextTokenId;
    address public fractionalVault;
    address public govAuthority;

    struct PropertyDetails {
        string name;
        string symbol;
        string location;
        uint256 size;
        string legalTitleHash;
        uint256 propertyPrice;
        bool isVerified;
    }

    mapping(uint256 => PropertyDetails) public propertyDetails;
    mapping(uint256 => bool) public isFractionalized;

    error ZeroAddress();
    error NotVault();
    error NotAuthority();
    error TokenDoesNotExist();
    error IncorrectOwner();
    error NotFractionalized();

    event PropertyMinted(uint256 indexed tokenId, address recipient, string tokenURI);
    event PropertyLocked(uint256 indexed tokenId, address vault);
    event PropertyUnlocked(uint256 indexed tokenId, address newOwner);
    event PropertyVerified(uint256 indexed tokenId, string legalTitleHash);
    event FractionalVaultSet(address indexed vault);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialOwner, address govAuth) external initializer {
        if (govAuth == address(0)) revert ZeroAddress();

        __ERC721_init("Real Estate NFT", "RE-NFT");
        __ERC721URIStorage_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();

        nextTokenId = 1;
        govAuthority = govAuth;

        _grantRole(DEFAULT_ADMIN_ROLE, initialOwner);
        _grantRole(UPGRADER_ROLE, initialOwner);
        _grantRole(AUTHORITY_ROLE, govAuth);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    modifier onlyVault() {
        if (msg.sender != fractionalVault) revert NotVault();
        _;
    }

    modifier onlyAuthorities() {
        if (!hasRole(AUTHORITY_ROLE, msg.sender)) revert NotAuthority();
        _;
    }

    function setFractionalVault(address _vault) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_vault == address(0)) revert ZeroAddress();
        fractionalVault = _vault;
        emit FractionalVaultSet(_vault);
    }

    // propertyPrice is stored as given — the caller (frontend) is responsible
    // for passing it already scaled to whatever precision it uses.
    function mintProperty(
        string memory symbol,
        string memory name,
        address recipient,
        string memory legalTitleHash,
        string memory location,
        uint256 size,
        uint256 propertyPrice
    ) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (recipient == address(0)) revert ZeroAddress();

        uint256 tokenId = nextTokenId++;
        _mint(recipient, tokenId);
        _setTokenURI(tokenId, legalTitleHash);
        propertyDetails[tokenId] = PropertyDetails(name, symbol, location, size, legalTitleHash, propertyPrice, false);
        emit PropertyMinted(tokenId, recipient, legalTitleHash);
    }

    function updateTokenURI(uint256 tokenId, string memory newURI) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (!_exists(tokenId)) revert TokenDoesNotExist();
        _setTokenURI(tokenId, newURI);
    }

    function verifyProperty(uint256 tokenId, string memory legalTitleHash) external onlyAuthorities {
        if (!_exists(tokenId)) revert TokenDoesNotExist();
        propertyDetails[tokenId].legalTitleHash = legalTitleHash;
        propertyDetails[tokenId].isVerified = true;
        emit PropertyVerified(tokenId, legalTitleHash);
    }

    function lockNFT(uint256 tokenId, address from) external onlyVault {
        if (ownerOf(tokenId) != from) revert IncorrectOwner();
        _transfer(from, fractionalVault, tokenId);
        isFractionalized[tokenId] = true;
        emit PropertyLocked(tokenId, fractionalVault);
    }

    function unlockNFT(uint256 tokenId, address newOwner) external onlyVault {
        if (!isFractionalized[tokenId]) revert NotFractionalized();
        _transfer(fractionalVault, newOwner, tokenId);
        isFractionalized[tokenId] = false;
        emit PropertyUnlocked(tokenId, newOwner);
    }

    function _burn(uint256 tokenId) internal override(ERC721Upgradeable, ERC721URIStorageUpgradeable) {
        super._burn(tokenId);
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721Upgradeable, ERC721URIStorageUpgradeable)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721Upgradeable, ERC721URIStorageUpgradeable, AccessControlUpgradeable)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }

    uint256[45] private __gap;
}

