// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "../RwaERC-3643/token/Token.sol";
import "./IFeeManager.sol";
import "./IFractionalVault.sol";

contract FractionalMarketplace is
    Initializable,
    AccessControlUpgradeable,
    ReentrancyGuardUpgradeable,
    UUPSUpgradeable
{
    using SafeERC20 for IERC20;

    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");
    bytes32 public constant AUTHORITY_ROLE = keccak256("AUTHORITY_ROLE");

    struct PropertyListing {
        address propertyToken;
        address owner;
        uint256 totalTokens;
        uint256 pricePerToken;
        uint256 remainingTokens;
        bool active;
        uint256 tokenId;
        bool buyBack;
        uint256 buyBackPrice;
        // Stablecoin the owner escrowed when activating buyback, minus what
        // has already been paid out to sellers. Funded up-front so a seller
        // calling sellTokensBack can never be refused (or drained out of the
        // owner's wallet beyond what they committed to).
        uint256 buyBackEscrow;
        // Timestamp after which the owner may reclaim whatever escrow is
        // left. Set to block.timestamp + BUYBACK_CLAIM_WINDOW on activation.
        uint256 buyBackDeadline;
    }

    /// @notice How long holders have to sell their shares back before the
    ///         owner can reclaim the unclaimed escrow. Without this the owner
    ///         could activate a buyback and immediately withdraw the deposit,
    ///         making the escrow guarantee meaningless.
    uint256 public constant BUYBACK_CLAIM_WINDOW = 60 days;

    IERC20 public stablecoin;
    IFeeManager public feeManager;
    address public vault;

    mapping(uint256 => PropertyListing) public listings;

    error ZeroAddress();
    error InvalidAmount();
    error InvalidPrice();
    error ListingAlreadyActive();
    error ListingNotActive();
    error NotOwner();
    error NotAuthorized();
    error BuyBackActive();
    error BuyBackNotActive();
    error BuyBackPriceTooLow();
    error TokensRemaining();
    error InvalidTreasury();
    error VaultNotSet();
    error NotVaultToken();
    error NoOutstandingTokens();
    error InsufficientEscrow();
    error NothingToWithdraw();
    error ClaimWindowOpen();

    event PropertyListed(uint256 indexed tokenId, address indexed owner, address propertyToken, uint256 totalTokens);
    event TokensBought(
        uint256 indexed tokenId, address indexed buyer, uint256 amount, uint256 totalPrice, uint256 fee
    );
    event ListingCancelled(uint256 indexed tokenId, address indexed owner, uint256 unsoldTokens);
    event PriceUpdated(uint256 indexed tokenId, uint256 newPricePerToken);
    event FractionsAdded(uint256 indexed tokenId, address indexed user, uint256 amount);
    event BuyBackActivated(uint256 indexed tokenId, uint256 buyBackPrice, uint256 depositedAmount, uint256 deadline);
    event BuyBackDepositWithdrawn(uint256 indexed tokenId, address indexed owner, uint256 amount);
    event TokenReceived(uint256 indexed tokenId, address indexed user, uint256 amount);
    event FeeManagerUpdated(address indexed oldFeeManager, address indexed newFeeManager);
    event VaultSet(address indexed vault);
    event SaleFeePaid(
        uint256 indexed tokenId, address indexed buyer, address indexed treasury, uint256 feeAmount, uint256 feeVersion
    );

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(address initialAdmin, address stablecoinAddress, address authority, address feeManagerAddress)
        external
        initializer
    {
        if (stablecoinAddress == address(0) || authority == address(0) || feeManagerAddress == address(0)) {
            revert ZeroAddress();
        }

        __AccessControl_init();
        __ReentrancyGuard_init();
        __UUPSUpgradeable_init();

        stablecoin = IERC20(stablecoinAddress);
        feeManager = IFeeManager(feeManagerAddress);

        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(UPGRADER_ROLE, initialAdmin);
        _grantRole(AUTHORITY_ROLE, authority);
    }

    function _authorizeUpgrade(address newImplementation) internal override onlyRole(UPGRADER_ROLE) {}

    function setFeeManager(address _feeManager) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_feeManager == address(0)) revert ZeroAddress();
        address oldFeeManager = address(feeManager);
        feeManager = IFeeManager(_feeManager);
        emit FeeManagerUpdated(oldFeeManager, _feeManager);
    }

    function setVault(address _vault) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (_vault == address(0)) revert ZeroAddress();
        vault = _vault;
        emit VaultSet(_vault);
    }

    // List tokens for sale
    function listProperty(address propertyToken, uint256 totalTokens, uint256 initialPricePerToken)
        external
        nonReentrant
    {
        if (totalTokens == 0) revert InvalidAmount();
        if (initialPricePerToken == 0) revert InvalidPrice();

        uint256 tokenId = Token(propertyToken).getTokenId();

        // propertyToken must be the actual share token the vault issued for
        // this property — otherwise anyone can deploy a fake token
        // returning a chosen getTokenId() and squat another property's
        // listing slot, permanently blocking the real owner.
        if (vault == address(0)) revert VaultNotSet();
        if (IFractionalVault(vault).getTokenAddressForProperty(tokenId) != propertyToken) revert NotVaultToken();

        PropertyListing storage listing = listings[tokenId];
        if (listing.propertyToken != address(0) && listing.active) revert ListingAlreadyActive();

        listings[tokenId] = PropertyListing({
            propertyToken: propertyToken,
            owner: msg.sender,
            totalTokens: totalTokens,
            pricePerToken: initialPricePerToken,
            remainingTokens: totalTokens,
            active: true,
            tokenId: tokenId,
            buyBack: false,
            buyBackPrice: 0,
            buyBackEscrow: 0,
            buyBackDeadline: 0
        });

        IERC20(propertyToken).safeTransferFrom(msg.sender, address(this), totalTokens);
        emit PropertyListed(tokenId, msg.sender, propertyToken, totalTokens);
    }

    // Add tokens to an existing listing
    function addTokensToListing(uint256 tokenId, uint256 additionalTokens) external nonReentrant {
        if (additionalTokens == 0) revert InvalidAmount();
        PropertyListing storage listing = listings[tokenId];
        if (!listing.active) revert ListingNotActive();
        if (msg.sender != listing.owner) revert NotOwner();

        IERC20(listing.propertyToken).safeTransferFrom(msg.sender, address(this), additionalTokens);

        listing.totalTokens += additionalTokens;
        listing.remainingTokens += additionalTokens;
        emit FractionsAdded(tokenId, msg.sender, additionalTokens);
    }

    // Users buy tokens
    function buyTokens(uint256 tokenId, uint256 amount) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        if (!listing.active) revert ListingNotActive();
        if (amount == 0 || amount > listing.remainingTokens) revert InvalidAmount();
        if (listing.buyBack) revert BuyBackActive();

        // Share tokens are whole units (FractionalVault.SHARE_DECIMALS == 0),
        // so pricePerToken is denominated directly in stablecoin units per
        // whole share — no decimals scaling to undo here.
        uint256 totalPrice = amount * listing.pricePerToken;
        if (totalPrice == 0) revert InvalidAmount();
        uint256 fee = _collectSaleFee(tokenId, totalPrice, msg.sender);

        stablecoin.safeTransferFrom(msg.sender, listing.owner, totalPrice);

        IERC20(listing.propertyToken).safeTransfer(msg.sender, amount);
        listing.remainingTokens -= amount;

        if (listing.remainingTokens == 0) {
            listing.active = false;
        }
        emit TokensBought(tokenId, msg.sender, amount, totalPrice, fee);
    }

    function _collectSaleFee(uint256 tokenId, uint256 totalPrice, address buyer) internal returns (uint256 fee) {
        uint256 feeVersion = feeManager.currentFeeVersion();
        IFeeManager.FeeConfig memory feeConfig = feeManager.getFeeConfig(feeVersion);
        if (feeConfig.saleFeeBps == 0) return 0;

        address treasury = feeManager.treasury();
        if (treasury == address(0)) revert InvalidTreasury();

        fee = (totalPrice * feeConfig.saleFeeBps) / feeManager.BPS_DENOMINATOR();
        stablecoin.safeTransferFrom(buyer, treasury, fee);
        emit SaleFeePaid(tokenId, buyer, treasury, fee, feeVersion);
    }

    // Owner cancels listing, reclaiming whatever's still unsold. Tokens
    // already bought by users stay with them — this does not require
    // remainingTokens == totalTokens, so the owner can pull their unsold
    // shares back (e.g. ahead of vault.redeemShares) even after a partial
    // sale.
    function cancelListing(uint256 tokenId) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        if (msg.sender != listing.owner) revert NotOwner();
        if (!listing.active) revert ListingNotActive();
        // A buyback with stablecoin still escrowed can't be cancelled out
        // from under the holders it was promised to — settle it first by
        // waiting out the claim window and calling withdrawBuyBackDeposit.
        if (listing.buyBackEscrow != 0) revert BuyBackActive();

        listing.active = false;
        listing.buyBack = false;
        uint256 unsoldTokens = listing.remainingTokens;
        listing.remainingTokens = 0;

        if (unsoldTokens > 0) {
            IERC20(listing.propertyToken).safeTransfer(msg.sender, unsoldTokens);
        }
        emit ListingCancelled(tokenId, msg.sender, unsoldTokens);
    }

    // Update price
    function updatePropertyPrice(uint256 tokenId, uint256 newPricePerToken) external {
        PropertyListing storage listing = listings[tokenId];
        if (!listing.active) revert ListingNotActive();
        if (msg.sender != listing.owner && !hasRole(AUTHORITY_ROLE, msg.sender)) revert NotAuthorized();
        if (newPricePerToken == 0) revert InvalidPrice();

        listing.pricePerToken = newPricePerToken;
        emit PriceUpdated(tokenId, newPricePerToken);
    }

    /// @notice Tokens sold out of this listing and still held by users — the
    ///         exact amount a buyback has to be able to repurchase.
    /// @dev    Shares still sitting unsold in the marketplace escrow
    ///         (`remainingTokens`) and shares the owner minted but never
    ///         listed are both still the owner's, so neither needs buying
    ///         back. Peer-to-peer OrderBook trades only move shares between
    ///         holders, leaving this figure correct.
    function outstandingTokens(uint256 tokenId) public view returns (uint256) {
        PropertyListing storage listing = listings[tokenId];
        return listing.totalTokens - listing.remainingTokens;
    }

    /// @notice Stablecoin `activateBuyBack(tokenId, buyBackPrice)` will pull
    ///         from the owner. Call this first to set the ERC-20 allowance.
    function buyBackDepositRequired(uint256 tokenId, uint256 buyBackPrice) public view returns (uint256) {
        return outstandingTokens(tokenId) * buyBackPrice;
    }

    /// @notice Owner opens a buyback, escrowing the full stablecoin cost of
    ///         repurchasing every outstanding share up-front. Requires an
    ///         allowance of `buyBackDepositRequired(tokenId, buyBackPrice)`.
    function activateBuyBack(uint256 tokenId, uint256 buyBackPrice) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        if (msg.sender != listing.owner) revert NotOwner();
        if (!listing.active) revert ListingNotActive();
        if (buyBackPrice == 0) revert InvalidPrice();
        if (listing.buyBack) revert BuyBackActive();

        // Buyback price must be at least 10% above the current listing price.
        uint256 minimumBuyBackPrice = (listing.pricePerToken * 110) / 100;
        if (buyBackPrice < minimumBuyBackPrice) revert BuyBackPriceTooLow();

        uint256 deposit = buyBackDepositRequired(tokenId, buyBackPrice);
        if (deposit == 0) revert NoOutstandingTokens();

        listing.buyBackPrice = buyBackPrice;
        listing.buyBack = true;
        listing.buyBackEscrow = deposit;
        listing.buyBackDeadline = block.timestamp + BUYBACK_CLAIM_WINDOW;

        stablecoin.safeTransferFrom(msg.sender, address(this), deposit);

        emit BuyBackActivated(tokenId, buyBackPrice, deposit, listing.buyBackDeadline);
    }

    function sellTokensBack(uint256 tokenId, uint256 amount) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        if (!listing.active) revert ListingNotActive();
        if (amount == 0) revert InvalidAmount();
        if (!listing.buyBack) revert BuyBackNotActive();

        uint256 refundAmount = amount * listing.buyBackPrice;
        // The escrow was sized for every outstanding share, so a legitimate
        // seller always fits; this only trips if shares were minted outside
        // the listing after the buyback opened.
        if (refundAmount > listing.buyBackEscrow) revert InsufficientEscrow();

        listing.buyBackEscrow -= refundAmount;
        listing.remainingTokens += amount;

        IERC20(listing.propertyToken).safeTransferFrom(msg.sender, address(this), amount);
        stablecoin.safeTransfer(msg.sender, refundAmount);

        emit TokenReceived(tokenId, msg.sender, amount);
    }

    /// @notice Owner reclaims the buyback stablecoin that holders never came
    ///         to claim. Locked until `buyBackDeadline`
    ///         (activation + BUYBACK_CLAIM_WINDOW) so the owner cannot
    ///         activate a buyback and immediately pull the deposit back out —
    ///         holders get the full window to sell back at the promised
    ///         price, and `sellTokensBack` keeps working right up to it.
    function withdrawBuyBackDeposit(uint256 tokenId) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        if (msg.sender != listing.owner) revert NotOwner();
        if (!listing.buyBack) revert BuyBackNotActive();
        if (block.timestamp < listing.buyBackDeadline) revert ClaimWindowOpen();

        uint256 amount = listing.buyBackEscrow;
        if (amount == 0) revert NothingToWithdraw();

        listing.buyBackEscrow = 0;
        stablecoin.safeTransfer(msg.sender, amount);

        emit BuyBackDepositWithdrawn(tokenId, msg.sender, amount);
    }

    uint256[45] private __gap;
}

