pragma solidity ^0.8.20;

import "@openzeppelin/contracts/proxy/ERC1967/ERC1967Proxy.sol";

/// @notice Thin wrapper so ERC1967Proxy gets its own compiled artifact for
/// Ignition deployments (Hardhat only emits artifacts for contracts declared
/// directly in this repo's own contracts/, not inherited node_modules bases).
contract UUPSProxy is ERC1967Proxy {
    constructor(address implementation, bytes memory _data) ERC1967Proxy(implementation, _data) {}
}
